"@

# Pattern más específico para encontrar el método completo
$pattern = '(?s)private void initializeQuestions\(\) \{.*?^\s{4}\}'

$content = $content -replace $pattern, $newInitMethod

# Guardar
Set-Content $filePath -Value $content -NoNewline

Write-Host "Actualización completada!" -ForegroundColor Green
Write-Host ""
Write-Host "QuizActivity ahora usa la base de datos SQLite." -ForegroundColor Cyan

# Script para reorganizar paquetes de quizgame a cinequiz
Write-Host "Reorganizando estructura de paquetes..." -ForegroundColor Cyan Write-Host ""
$basePath = "C:\Users\rpcla\AndroidStudioProjects\QuizGame\app\src\main\java\com\example" $oldPackage = "$basePath\quizgame" $newPackage = "$basePath\cinequiz"
# 1. Crear nuevo directorio cinequiz Write-Host "1. Creando directorio cinequiz..." -ForegroundColor Yellow if (-not (Test-Path $newPackage)) { New-Item -ItemType Directory -Path $newPackage -Force | Out-Null Write-Host " Directorio creado" -ForegroundColor Green } else { Write-Host " Directorio ya existe" -ForegroundColor Green }
# 2. Leer y actualizar cada archivo Java Write-Host "2. Actualizando archivos Java..." -ForegroundColor Yellow
$javaFiles = @("MainActivity.java", "ManualActivity.java", "Question.java", "QuizActivity.java", "ResultActivity.java")
foreach ($file in $javaFiles) { $oldPath = "$oldPackage\$file" $newPath = "$newPackage\$file"
if (Test-Path $oldPath) { # Leer contenido $content = Get-Content $oldPath -Raw
# Cambiar declaración de paquete $content = $content -replace 'package com\.example\.quizgame;', 'package com.example.cinequiz;'
# Guardar en nueva ubicación Set-Content $newPath -Value $content -NoNewline
Write-Host " $file actualizado y movido" -ForegroundColor Green } }
# 3. Eliminar directorio antiguo Write-Host "3. Eliminando directorio quizgame antiguo..." -ForegroundColor Yellow if (Test-Path $oldPackage) { Remove-Item -Path $oldPackage -Recurse -Force Write-Host " Directorio antiguo eliminado" -ForegroundColor Green }
# 4. Actualizar también los directorios de test si existen Write-Host "4. Actualizando directorios de test..." -ForegroundColor Yellow
$testPath = "C:\Users\rpcla\AndroidStudioProjects\QuizGame\app\src\test\java\com\example" $androidTestPath = "C:\Users\rpcla\AndroidStudioProjects\QuizGame\app\src\androidTest\java\com\example"
if (Test-Path "$testPath\quizgame") { if (-not (Test-Path "$testPath\cinequiz")) { New-Item -ItemType Directory -Path "$testPath\cinequiz" -Force | Out-Null }
Get-ChildItem -Path "$testPath\quizgame" -File | ForEach-Object { $content = Get-Content $_.FullName -Raw $content = $content -replace 'package com\.example\.quizgame', 'package com.example.cinequiz' Set-Content "$testPath\cinequiz\$($_.Name)" -Value $content -NoNewline }
Remove-Item -Path "$testPath\quizgame" -Recurse -Force Write-Host " Test actualizado" -ForegroundColor Green }
if (Test-Path "$androidTestPath\quizgame") { if (-not (Test-Path "$androidTestPath\cinequiz")) { New-Item -ItemType Directory -Path "$androidTestPath\cinequiz" -Force | Out-Null }
Get-ChildItem -Path "$androidTestPath\quizgame" -File | ForEach-Object { $content = Get-Content $_.FullName -Raw $content = $content -replace 'package com\.example\.quizgame', 'package com.example.cinequiz' Set-Content "$androidTestPath\cinequiz\$($_.Name)" -Value $content -NoNewline }
Remove-Item -Path "$androidTestPath\quizgame" -Recurse -Force Write-Host " AndroidTest actualizado" -ForegroundColor Green }
Write-Host "" Write-Host "==================================================" -ForegroundColor Cyan Write-Host "Reorganización completada!" -ForegroundColor Green Write-Host "==================================================" -ForegroundColor Cyan Write-Host "" Write-Host "Paquete cambiado de:" -ForegroundColor Yellow Write-Host " com.example.quizgame" -ForegroundColor White Write-Host "a:" -ForegroundColor Yellow Write-Host " com.example.cinequiz" -ForegroundColor White Write-Host "" Write-Host "Ahora sincroniza el proyecto en Android Studio." -ForegroundColor Cyan

pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\.android.*")
                includeGroupByRegex("com\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "CineQuiz"
include ':app'
